package mswkst

import (
	"github.com/TheManticoreProject/Manticore/network/dcerpc/ndr"
)

// USE_ENUM_STRUCT ([MS-WKST]). Generated by tools/idlgen; verify pointer/array tags.
type USE_ENUM_STRUCT struct {
	Level   ndr.DWORD
	UseInfo USE_ENUM_UNION
}

// USE_ENUM_UNION is a discriminated union ([MS-WKST] 2.2.5.23). switch_type is DWORD; the
// discriminant is transmitted inline before the selected arm ([C706] 14.3.8). Every arm is a
// [unique] pointer container (LPUSE_INFO_0_CONTAINER, ...), so each arm is a pointer field
// with `unique`; an inline-value arm would drop the container referent id and desync decode.
type USE_ENUM_UNION struct {
	Tag    ndr.DWORD             `ndr:"switch"`
	Level0 *USE_INFO_0_CONTAINER `ndr:"case=0,unique"`
	Level1 *USE_INFO_1_CONTAINER `ndr:"case=1,unique"`
	Level2 *USE_INFO_2_CONTAINER `ndr:"case=2,unique"`
}
